      paint();
    });
    document.getElementById('status').textContent =
      'Cover ready — click a panel, then a tray photo, to swap it.';
  }

  drawCover(canvas, state, 1);
  window.__shotReady = true;
  window.__viceCutShot = { params, state };
}

runShot().catch((error) => {
